window.CARDS=window.CARDS||{};CARDS["story-v-y1v5-index"]=[{"i":"sc-sudou-ken-y1v5-p11-1","v":"y1v5","y":1,"o":6,"k":"inner","w":"sudou-ken","q":"sudo ken ch 1  the soliloquy volume cold open  sudou s first person soliloquy alone with his backstory  no other character appears  and p 12 carries no prose   to be completely honest  i ain t really a capable person  his mother abandoned the family to go into the nightclub business  his father toiled as a janitor with a permanently hunched back  and the sight of it sickened him   being the idiot i am  i decided to give up on studyin  and go into sports    he chose getting stronger over studying and frames it as his own idea  not a defeat  solo sports first   tennis and pingpong  good but never top tier   then basketball  despite not being a team player he got seriously into it  kept improving  and was recommended to a high school with one of the best basketball teams in the entire country  the pulled recommendation defines his self read   that was when i really understood the painful truth  i was trash  born from trash  chose this school for what it promised   that was why i chose this school    free  and able to guarantee even his future  blank short scan page  running footer only  no prose to cite","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p11-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y1v5-p11-1\">Ch.1: the soliloquy<\/a><\/span><span class=\"meta\">Y1V5 · p.11–12<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Volume cold open: Sudou’s first-person soliloquy alone with his backstory; no other character appears, and p.12 carries no prose.<\/p><ul class=\"lines\"><li class=\"q inner\"><b class=\"sp\">Sudō Ken<\/b> “To be completely honest, I ain’t really a capable person.”<span class=\"pg\">p.11<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Fact<\/span> His mother abandoned the family to go into the nightclub business; his father toiled as a janitor with a permanently hunched back, and the sight of it sickened him.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> “Being the idiot I am, I decided to give up on studyin’ and go into sports.” — he chose getting stronger over studying and frames it as his own idea, not a defeat.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Solo sports first — tennis and pingpong, good but never top-tier — then basketball: despite not being a team player he got seriously into it, kept improving, and was recommended to a high school with one of the best basketball teams in the entire country.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> The pulled recommendation defines his self-read: “That was when I really understood the painful truth: I was trash, born from trash.”<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Trait<\/span> Chose this school for what it promised: “That was why I chose this school.” — free, and able to guarantee even his future.<span class=\"pg\">p.11<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Blank/short scan page: running footer only; no prose to cite.<span class=\"pg\">p.12<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p16-1\">→ After: Ch.2 §2.1: the huddle<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v5-p13-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"karuizawa-kei hirata-yousuke horikita-suzune sudou-ken ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 2  the zodiac debrief at pallet back table of the crowded cafe pallet after summer vacation  ayanokoji sits with hirata  karuizawa and horikita  reviewing the cruise ship zodiac exam and its hidden vips  the rabbit group read alphabetically   ayanokouji kun  ichinose san  ibuki san  karuizawa san   made him the rabbit vip  the dragon group s fifth name was kushida san   i honestly don t have a clue    lied to the group when horikita asked what he thought  notices karuizawa has started calling hirata yousuke kun  he meets her gaze and she diverts her eyes  plays along as the cooperative nobody while hirata works to cement the four person group  exchanges the no presence   long shadows banter with her  she is not joking when she takes the bait  names sudou among the athletic students the festival is built to give their first real opening","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v5-p13-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v5-p13-1\">Ch.2: the zodiac debrief at Pallet<\/a><\/span><span class=\"meta\">Y1V5 · p.13–15<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Back table of the crowded café Pallet after summer vacation: Ayanokōji sits with Hirata, Karuizawa and Horikita, reviewing the cruise-ship zodiac exam and its hidden VIPs.<\/p><p class=\"with\">with <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I honestly don’t have a clue” — lied to the group when Horikita asked what he thought.<span class=\"pg\">p.14<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Fact<\/span> The rabbit group read alphabetically — Ayanokouji-kun, Ichinose-san, Ibuki-san, Karuizawa-san — made him the rabbit VIP; the dragon group’s fifth name was Kushida-san.<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Notices Karuizawa has started calling Hirata Yousuke-kun; he meets her gaze and she diverts her eyes.<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Plays along as the cooperative nobody while Hirata works to cement the four-person group.<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Exchanges the no-presence / long-shadows banter with her; she is not joking when she takes the bait.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Names Sudou among the athletic students the festival is built to give their first real opening.<span class=\"pg\">p.16<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p16-1\">→ After: Ch.2 §2.1: the rules and the huddle<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v5-p13-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"kushida-kikyou horikita-suzune hirata-yousuke","q":"hirata yosuke ch 2  the zodiac debrief at pallet at pallet he keeps the two girls  friction down   his presence makes the discomfort between karuizawa and horikita mysteriously disappear   i think ryuuen kun figured it all out in the middle of the test   if he understood the rules  he should have discovered all the vips   i m glad we re discussing this  horikita san and ayanokouji kun   i actually have a proposal   first  to bring our class together  i d like to rope in kushida san as an ally  proposes her as the fourth ally to unite the boys   starting with ike kun and yamauchi kun   over horikita s refusal  his proposal is rejected  she side eyes ayanokoji instead of softening","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v5-p13-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v5-p13-1\">Ch.2: the zodiac debrief at Pallet<\/a><\/span><span class=\"meta\">Y1V5 · p.13–15<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">At Pallet he keeps the two girls’ friction down — his presence makes the discomfort between Karuizawa and Horikita mysteriously disappear.<\/p><p class=\"with\">with <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a> · <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “I think Ryuuen-kun figured it all out in the middle of the test,”<span class=\"pg\">p.13<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “If he understood the rules, he should have discovered all the VIPs,”<span class=\"pg\">p.14<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “I’m glad we’re discussing this, Horikita-san and Ayanokouji-kun,”<span class=\"pg\">p.14<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I actually have a proposal.”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “First, to bring our class together, I’d like to rope in Kushida-san as an ally.”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Kushida Kikyō<\/b> Proposes her as the fourth ally to unite the boys — starting with Ike-kun and Yamauchi-kun — over Horikita’s refusal.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> His proposal is rejected; she side-eyes Ayanokōji instead of softening.<span class=\"pg\">p.15<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v5-p16-1\">→ After: Ch.2 §2.1: the briefing<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y1v5-p13-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"karuizawa-kei horikita-suzune","q":"horikita suzune ch 2  the zodiac debrief at pallet at pallet with hirata  karuizawa and ayanokoji  she walks the rabbit group through the alphabetical vip rule and the cruise ship exam s logic   if you put the names of the students in the rabbit group in alphabetical order  it would be ayanokouji kun  ichinose san  ibuki san  and then karuizawa san  confirms karuizawa s dragon group deduction   kushida fifth   and explains why the pattern was hard to see mid exam   though it appears that ryuuen kun rules class c alone  perhaps that isn t actually true   a rebellious student must ve tossed out the wrong answer in direct defiance of ryuuen kun   that said  you evaded ryuuen kun s clutches quite well    aims it at karuizawa   unnecessary    refuses hirata s proposal to rope kushida in   i won t deny the fact that she has certain skills  but we can do anything she can on our own   those who claim that they have no presence usually cast long shadows   do you take me for a fool    stung by ayanokoji s no presence bait  not joking","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v5-p13-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v5-p13-1\">Ch.2: the zodiac debrief at Pallet<\/a><\/span><span class=\"meta\">Y1V5 · p.13–15<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">At Pallet with Hirata, Karuizawa and Ayanokōji, she walks the rabbit group through the alphabetical VIP rule and the cruise-ship exam’s logic.<\/p><p class=\"with\">with <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “If you put the names of the students in the rabbit group in alphabetical order, it would be Ayanokouji-kun, Ichinose-san, Ibuki-san, and then Karuizawa-san,”<span class=\"pg\">p.13<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Though it appears that Ryuuen-kun rules Class C alone, perhaps that isn’t actually true.”<span class=\"pg\">p.14<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “A rebellious student must’ve tossed out the wrong answer in direct defiance of Ryuuen-kun.”<span class=\"pg\">p.14<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> Confirms Karuizawa’s dragon-group deduction — Kushida fifth — and explains why the pattern was hard to see mid-exam.<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That said, you evaded Ryuuen-kun’s clutches quite well.” — aims it at Karuizawa.<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Unnecessary,” — refuses Hirata’s proposal to rope Kushida in.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I won’t deny the fact that she has certain skills, but we can do anything she can on our own.”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Those who claim that they have no presence usually cast long shadows,”<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Do you take me for a fool?” — stung by Ayanokōji’s no-presence bait; not joking.<span class=\"pg\">p.15<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v5-p16-1\">→ After: Ch.2 §2.1: the briefing and the huddle<\/button><\/div><\/article>"},{"i":"sc-ibuki-mio-y1v5-p13-1","v":"y1v5","y":1,"o":6,"k":"","w":"horikita-suzune ibuki-mio","q":"ibuki mio ch 2  passing mention named in the alphabetical rabbit group roster karuizawa recites   third  between ichinose san and karuizawa san  her place in the roster is the exhibit for the zodiac vip rule","h":"<article class=\"card\" id=\"sc-ibuki-mio-y1v5-p13-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ibuki-mio.html#sc-ibuki-mio-y1v5-p13-1\">Ch.2: passing mention<\/a><\/span><span class=\"meta\">Y1V5 · p.13<\/span><span class=\"by\">notes on <a href=\"../../../people/ibuki-mio.html\">Ibuki Mio<\/a><\/span><\/h3><p class=\"setup\">Named in the alphabetical rabbit-group roster Karuizawa recites — third, between Ichinose-san and Karuizawa-san.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Her place in the roster is the exhibit for the zodiac VIP rule.<span class=\"pg\">p.13<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-karuizawa-kei-y1v5-p13-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-suzune hirata-yousuke ayanokouji-kiyotaka karuizawa-kei","q":"karuizawa kei ch 2  the zodiac debrief at pallet at pallet she works through the rabbit group s alphabetical vip order and lands on her own role in the cruise ship exam   that s why i was chosen as vip   but isn t that really  really simple    on the dragon group s fifth name giveaway for kushida  sits with her at pallet   the two girls are completely incompatible at first glance  but hirata s presence erases the discomfort  has started calling him yousuke kun  hugs his arm  and asks him to confirm her poker face   ayanokoji notices the shift   i do have a surprisingly good poker face  keeps her eyes on him after the others lose interest  he meets her gaze and she diverts hers","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y1v5-p13-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y1v5-p13-1\">Ch.2: the zodiac debrief at Pallet<\/a><\/span><span class=\"meta\">Y1V5 · p.13–15<\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><p class=\"setup\">At Pallet she works through the rabbit group’s alphabetical VIP order and lands on her own role in the cruise-ship exam.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “That’s why I was chosen as VIP”<span class=\"pg\">p.13<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “But isn’t that really, really simple?” — on the dragon group’s fifth-name giveaway for Kushida.<span class=\"pg\">p.13<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Karuizawa Kei<\/b> “I do have a surprisingly good poker face.”<span class=\"pg\">p.14<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Sits with her at Pallet — the two girls are completely incompatible at first glance, but Hirata’s presence erases the discomfort.<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Has started calling him Yousuke-kun, hugs his arm, and asks him to confirm her poker face — Ayanokōji notices the shift.<span class=\"pg\">p.14<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Keeps her eyes on him after the others lose interest; he meets her gaze and she diverts hers.<span class=\"pg\">p.14<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v5-p28-1\">→ After: Ch.2 §2.2: the Class C exit<\/button><\/div><\/article>"},{"i":"sc-kushida-kikyou-y1v5-p13-1","v":"y1v5","y":1,"o":6,"k":"","w":"horikita-suzune hirata-yousuke sakayanagi-arisu kushida-kikyou","q":"kushida kikyo ch 2  passing mentions named in the zodiac recap as the dragon group s fifth name and therefore its vip  again at p 15 as hirata s proposed ally and at p 30 as a beauty benchmark  her name is the exhibit for the alphabetical vip rule horikita walks through  hirata wants her roped in to unite the boys  horikita refuses  sakayanagi is called  as cute as kushida and sakura  in narration","h":"<article class=\"card\" id=\"sc-kushida-kikyou-y1v5-p13-1\"><h3><span class=\"ttl\"><a href=\"../../../people/kushida-kikyou.html#sc-kushida-kikyou-y1v5-p13-1\">Ch.2: passing mentions<\/a><\/span><span class=\"meta\">Y1V5 · p.13, 15, 30<\/span><span class=\"by\">notes on <a href=\"../../../people/kushida-kikyou.html\">Kushida Kikyō<\/a><\/span><\/h3><p class=\"setup\">Named in the zodiac recap as the dragon group’s fifth name and therefore its VIP; again at p.15 as Hirata’s proposed ally and at p.30 as a beauty benchmark.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Her name is the exhibit for the alphabetical VIP rule Horikita walks through.<span class=\"pg\">p.13<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Hirata wants her roped in to unite the boys; Horikita refuses.<span class=\"pg\">p.15<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Sakayanagi is called “as cute as Kushida and Sakura” in narration.<span class=\"pg\">p.30<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-sports-festival-y1v5-p16-1","v":"y1v5","y":1,"o":6,"k":"","w":"horikita-suzune chabashira-sae","q":"sports festival ch 2  2 1  the rules briefing chabashira s two hour homeroom hands out the printed sports festival rules  september to early october becomes heavy physical education  classes a and d form the red team  classes b and c the white team  across all grade levels  class d competes alongside class a  individual events score 15 12 10 8  fifth place loses one point and each place below loses one more  a team competition win is worth 500  recommended participant events score 50 30 15 10  fifth loses two points and each place below loses two more  the 1200 metre relay pays three times those values  after combined class scores are reviewed  100 class points are deducted from the first  second  and third year batches of the two classes on the losing team  chabashira adds that points move class by class  not just by team  even a red team win can still hit class d with the 100 point penalty if it holds the lowest combined overall score  grade ranking is separate  50 class points to each grade s first place class  no change for second  50 deducted for third  100 for fourth  an individual winner chooses 5000 private points or three written test points  second chooses 3000 or two  third chooses 1000 or one  test points taken this way cannot be given to another student  the lowest scorer in an individual competition loses 1000 private points  or one written test point if they hold fewer than 1000  overall mvp takes 100 000 private points  each grade s top three scorers take 10 000 private points apiece  the ten lowest scoring students in each year lose ten points on their next written exam  thirteen events in order  100 metre dash  hurdle race  capture the flag  boys  ball toss  girls  tug of war by sex  obstacle course race  three legged race  cavalry battle  200 metre dash  then scavenger hunt  four way tug of war  mixed three legged race  and the mixed grade 1200 metre relay  the participation table must be a class consensus  the window opens one week before the festival and closes at 5 00 pm the day before  a missed window means random assignment  falling below the minimum for an all participant event means disqualification  a recommended event substitute can be bought for 100 000 private points per competition  her absence and health questions draw out the substitute price and the student decides health policy  delivers the whole briefing in a detached  matter of fact manner and lets out one slight laugh at ike s question","h":"<article class=\"card\" id=\"sc-sports-festival-y1v5-p16-1\"><h3><span class=\"ttl\"><a href=\"../../../school/exam/sports-festival.html#sc-sports-festival-y1v5-p16-1\">Ch.2 §2.1: the rules briefing<\/a><\/span><span class=\"meta\">Y1V5 · p.16–23<\/span><span class=\"by\">notes on <a href=\"../../../school/exam/sports-festival.html\">Sports Festival<\/a><\/span><\/h3><p class=\"setup\">Chabashira’s two-hour homeroom hands out the printed sports festival rules; September to early October becomes heavy physical education.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/p><details class=\"more\"><summary>15 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Rule<\/span> Classes A and D form the Red Team, Classes B and C the White Team, across all grade levels; Class D competes alongside Class A.<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Individual events score 15/12/10/8; fifth place loses one point and each place below loses one more; a team-competition win is worth 500.<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Recommended-participant events score 50/30/15/10; fifth loses two points and each place below loses two more; the 1200-metre relay pays three times those values.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> After combined class scores are reviewed, 100 class points are deducted from the first-, second- and third-year batches of the two classes on the losing team.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Chabashira adds that points move class-by-class, not just by team: even a Red Team win can still hit Class D with the 100-point penalty if it holds the lowest combined overall score.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Grade ranking is separate: 50 class points to each grade’s first-place class, no change for second, 50 deducted for third, 100 for fourth.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> An individual winner chooses 5000 private points or three written-test points, second chooses 3000 or two, third chooses 1000 or one; test points taken this way cannot be given to another student.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> The lowest scorer in an individual competition loses 1000 private points, or one written-test point if they hold fewer than 1000.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Overall MVP takes 100,000 private points; each grade’s top three scorers take 10,000 private points apiece.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> The ten lowest-scoring students in each year lose ten points on their next written exam.<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Thirteen events in order: 100-metre dash, hurdle race, capture the flag (boys), ball toss (girls), tug-of-war by sex, obstacle course race, three-legged race, cavalry battle, 200-metre dash; then scavenger hunt, four-way tug-of-war, mixed three-legged race, and the mixed-grade 1200-metre relay.<span class=\"pg\">p.21<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> The participation table must be a class consensus; the window opens one week before the festival and closes at 5:00 pm the day before; a missed window means random assignment.<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Falling below the minimum for an all-participant event means disqualification; a recommended-event substitute can be bought for 100,000 private points per competition.<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Her absence and health questions draw out the substitute price and the student-decides health policy.<span class=\"pg\">p.22–23<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> Delivers the whole briefing in a detached, matter-of-fact manner and lets out one slight laugh at Ike’s question.<span class=\"pg\">p.16<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sports-festival-y1v5-p26-1\">→ After: Ch.2 §2.2: the assembly<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v5-p16-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-suzune ike-kanji yamauchi-haruki ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 2  2 1  the rules and the huddle afternoon homeroom becomes a two hour session  chabashira announces the september sports festival and its handout  the class erupts  teases her about finally having an opportunity to get in touch with her brother on the red team  she glares and tells him to drop it   at least you have an opportunity to get in touch now  huh  watches the huddle from the side   ike and yamauchi push for personal chances against the class s interest  yamauchi is present at the huddle  no line of his is tagged in the translation   it s a sad fact of reality    answering horikita s complaint that only guys like these come to her","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v5-p16-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v5-p16-1\">Ch.2 §2.1: the rules and the huddle<\/a><\/span><span class=\"meta\">Y1V5 · p.16–25<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Afternoon homeroom becomes a two-hour session: Chabashira announces the September sports festival and its handout; the class erupts.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “At least you have an opportunity to get in touch now, huh?”<span class=\"pg\">p.17<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “It’s a sad fact of reality,” — answering Horikita’s complaint that only guys like these come to her.<span class=\"pg\">p.23<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Teases her about finally having an opportunity to get in touch with her brother on the Red Team; she glares and tells him to drop it.<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Watches the huddle from the side — Ike and Yamauchi push for personal chances against the class’s interest.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> Yamauchi is present at the huddle; no line of his is tagged in the translation.<span class=\"pg\">p.24<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p13-1\">← Before: Ch.2: the zodiac debrief at Pallet<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p26-1\">→ After: Ch.2 §2.2: the Red Team assembly<\/button><\/div><\/article>"},{"i":"sc-chabashira-sae-y1v5-p16-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"chabashira-sae","q":"chabashira sae ch 2  2 1  the sports festival briefing afternoon homeroom runs two hours  she distributes the festival handout and weekly schedules in a detached  matter of fact manner   however  from september to the beginning of october  we will be holding more physical education classes to prepare for the school sports festival   in any case  this event will massively impact each and every class    answers hirata s special exam question vaguely  explains the red white split   class d and class a ride the red team together   you in class d are assigned to the red team   their reward will be not having any points deducted    the cruel  brief answer to the winning team question   in the sports festival  you can earn test points as a prize  which you can then apply to a written exam    lets out a slight laugh  an unusual sight  reads out the ten lowest penalty  for first years  ten points off the next written exam   should you fall short of the minimum required number of people for competitions for all participants  you will be deemed unable to continue and disqualified   a substitute requires 100 000 private points per competition   next period s location will move to gymnasium 1  where you ll meet with students from other classes and grade levels","h":"<article class=\"card\" id=\"sc-chabashira-sae-y1v5-p16-1\"><h3><span class=\"ttl\"><a href=\"../../../people/chabashira-sae.html#sc-chabashira-sae-y1v5-p16-1\">Ch.2 §2.1: the sports festival briefing<\/a><\/span><span class=\"meta\">Y1V5 · p.16–25<\/span><span class=\"by\">notes on <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/span><\/h3><p class=\"setup\">Afternoon homeroom runs two hours: she distributes the festival handout and weekly schedules in a detached, matter-of-fact manner.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “However, from September to the beginning of October, we will be holding more physical education classes to prepare for the school sports festival.”<span class=\"pg\">p.16<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “In any case, this event will massively impact each and every class.” — answers Hirata’s special-exam question vaguely.<span class=\"pg\">p.16<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “You in Class D are assigned to the Red Team.”<span class=\"pg\">p.17<\/span><\/li><\/ul><details class=\"more\"><summary>7 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Post<\/span> Explains the Red/White split — Class D and Class A ride the Red Team together.<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Their reward will be not having any points deducted.” — the cruel, brief answer to the winning-team question.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “In the sports festival, you can earn test points as a prize, which you can then apply to a written exam.” — lets out a slight laugh, an unusual sight.<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Post<\/span> Reads out the ten-lowest penalty: for first-years, ten points off the next written exam.<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Should you fall short of the minimum required number of people for competitions for all participants, you will be deemed unable to continue and disqualified,”<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “A substitute requires 100,000 private points per competition.”<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Next period’s location will move to Gymnasium 1, where you’ll meet with students from other classes and grade levels.”<span class=\"pg\">p.23<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v5-p35-1\">→ After: Ch.2 §2.3: the gate<\/button><\/div><\/article>"},{"i":"sc-hirata-yousuke-y1v5-p16-1","v":"y1v5","y":1,"o":6,"k":"action spoken","w":"hirata-yousuke","q":"hirata yosuke ch 2  2 1  the briefing in homeroom he is the first to ask whether the festival is another special exam  chabashira s answer stays vague   sensei  is this festival another of the special exams   um  sensei  how many points does the winning team get    chabashira answers  none   wait  so  we can decide the order in which we ll participate    on the participation table  the absence questions in the room are his and horikita s   both read the handout like exam material","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v5-p16-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v5-p16-1\">Ch.2 §2.1: the briefing<\/a><\/span><span class=\"meta\">Y1V5 · p.16–25<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">In homeroom he is the first to ask whether the festival is another special exam; Chabashira’s answer stays vague.<\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “Sensei, is this festival another of the special exams?”<span class=\"pg\">p.16<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “Um, sensei, how many points does the winning team get?” — Chabashira answers: none.<span class=\"pg\">p.18<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “Wait. So, we can decide the order in which we’ll participate?” — on the participation table.<span class=\"pg\">p.22<\/span><\/li><\/ul><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">What happens<\/span> The absence questions in the room are his and Horikita’s — both read the handout like exam material.<span class=\"pg\">p.22<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v5-p13-1\">← Before: Ch.2: the zodiac debrief at Pallet<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v5-p26-1\">→ After: Ch.2 §2.2: the assembly<\/button><\/div><\/article>"},{"i":"sc-horikita-suzune-y1v5-p16-1","v":"y1v5","y":1,"o":6,"k":"action spoken","w":"horikita-manabu horikita-suzune","q":"horikita suzune ch 2  2 1  the briefing and the huddle in homeroom she spots the testing method on the handout before most of the class and calls ayanokoji over  at the mention that class a   her brother s year   rides the same red team  she mutters at ayanokoji to drop it   don t talk about that here  after hirata s practical questions she raises her own  what happens on the day if someone is absent from a group competition   well  how many points are needed to assign a substitute  sudou  ike and yamauchi corner her in the free homeroom period to argue the festival strategy   why do only guys like these come to me   that s not a valid opinion    shuts down ike s fun and win line at once   within our class  you stand out as someone with superior athletic skill    concedes sudou s claim on the recommended events   stamina isn t an unlimited resource    her counter to entering sudou in everything   we re not coming to any decisions right now    ends the huddle without a decision","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v5-p16-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v5-p16-1\">Ch.2 §2.1: the briefing and the huddle<\/a><\/span><span class=\"meta\">Y1V5 · p.16–25<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">In homeroom she spots the testing method on the handout before most of the class and calls Ayanokōji over. Sudou, Ike and Yamauchi corner her in the free homeroom period to argue the festival strategy.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Don’t talk about that here,”<span class=\"pg\">p.17<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Well, how many points are needed to assign a substitute?”<span class=\"pg\">p.23<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Why do only guys like these come to me?”<span class=\"pg\">p.23<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> At the mention that Class A — her brother’s year — rides the same Red Team, she mutters at Ayanokōji to drop it.<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> After Hirata’s practical questions she raises her own: what happens on the day if someone is absent from a group competition?<span class=\"pg\">p.22<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s not a valid opinion.” — shuts down Ike’s fun-and-win line at once.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Within our class, you stand out as someone with superior athletic skill.” — concedes Sudou’s claim on the recommended events.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Stamina isn’t an unlimited resource.” — her counter to entering Sudou in everything.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We’re not coming to any decisions right now.” — ends the huddle without a decision.<span class=\"pg\">p.25<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v5-p13-1\">← Before: Ch.2: the zodiac debrief at Pallet<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v5-p26-1\">→ After: Ch.2 §2.2: the assembly and the coin<\/button><\/div><\/article>"},{"i":"sc-sudou-ken-y1v5-p16-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-suzune ike-kanji sudou-ken","q":"sudo ken ch 2  2 1  the huddle named as one of the athletic students fired up by the sports festival   probably the first exam that lets him contribute meaningfully  his athletic ability is the class s read on him before the events are even set  pulls ike and yamauchi to her and opens the strategy huddle   let s figure this out  horikita   class d can win this   if i do that  we ll win    claims every recommended participant event  tells ike flatly that the recommended events belong to people who are good at sports   you re not  kanji  pushes back on her stamina caution   even tired  he moves better than the unathletic guys   and leaves without a decision   but it s better to leave it to me than put forward someone unathletic  right","h":"<article class=\"card\" id=\"sc-sudou-ken-y1v5-p16-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sudou-ken.html#sc-sudou-ken-y1v5-p16-1\">Ch.2 §2.1: the huddle<\/a><\/span><span class=\"meta\">Y1V5 · p.16, 23–25<\/span><span class=\"by\">notes on <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/span><\/h3><p class=\"setup\">Named as one of the athletic students fired up by the sports festival — probably the first exam that lets him contribute meaningfully.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “Let’s figure this out, Horikita,”<span class=\"pg\">p.23<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “Class D can win this,”<span class=\"pg\">p.24<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sudō Ken<\/b> “If I do that, we’ll win,” — claims every recommended-participant event.<span class=\"pg\">p.24<\/span><\/li><\/ul><details class=\"more\"><summary>6 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Feat<\/span> His athletic ability is the class’s read on him before the events are even set.<span class=\"pg\">p.16<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Pulls Ike and Yamauchi to her and opens the strategy huddle.<span class=\"pg\">p.23<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> Tells Ike flatly that the recommended events belong to people who are good at sports.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re not, Kanji,”<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> Pushes back on her stamina caution — even tired, he moves better than the unathletic guys — and leaves without a decision.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But it’s better to leave it to me than put forward someone unathletic, right?”<span class=\"pg\">p.24<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sudou-ken-y1v5-p11-1\">← Before: Ch.1: the soliloquy<\/button><\/div><\/article>"},{"i":"sc-ike-kanji-y1v5-p17-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"sudou-ken yamauchi-haruki sakayanagi-arisu ike-kanji","q":"ike kanji ch 2  the briefing and the huddle shouts at the red white announcement  then joins sudou and yamauchi in crowding horikita for strategy   whoa  seriously  we re really doing that   yeah  yeah  let s think of a way to win   i d like to have fun and win    smacked down by horikita at once   hey  you don t know that for sure    miracles happen  and it should be fair  takes sudou s  you re not  kanji  without an answer  frustrated but silent by the end of the huddle  the pair are dissatisfied together  the translation never tags which boy speaks the  we want a chance  lines  whispers  hey  check out that girl  pointing at the class a girl with the cane   he s smitten like the rest   hey  check out that girl","h":"<article class=\"card\" id=\"sc-ike-kanji-y1v5-p17-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ike-kanji.html#sc-ike-kanji-y1v5-p17-1\">Ch.2: the briefing and the huddle<\/a><\/span><span class=\"meta\">Y1V5 · p.17, 23–27<\/span><span class=\"by\">notes on <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a><\/span><\/h3><p class=\"setup\">Shouts at the Red/White announcement, then joins Sudou and Yamauchi in crowding Horikita for strategy.<\/p><p class=\"with\">with <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a> · <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> “Whoa! Seriously?! We’re really doing that?”<span class=\"pg\">p.17<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> “Yeah, yeah, let’s think of a way to win!”<span class=\"pg\">p.23<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ike Kanji<\/b> “I’d like to have fun and win!” — smacked down by Horikita at once.<span class=\"pg\">p.24<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “Hey, you don’t know that for sure!” — miracles happen, and it should be fair.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Takes Sudou’s “You’re not, Kanji,” without an answer; frustrated but silent by the end of the huddle.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Yamauchi Haruki<\/b> The pair are dissatisfied together; the translation never tags which boy speaks the “we want a chance” lines.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Whispers “Hey, check out that girl,” pointing at the Class A girl with the cane — he’s smitten like the rest.<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Hey, check out that girl,”<span class=\"pg\">p.27<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-private-points-y1v5-p17-1","v":"y1v5","y":1,"o":6,"k":"","w":"","q":"private points ch 2  the sports festival s point economy chabashira s handout prices the school sports festival in private points  test points and class points at once  individual competition placement pays 15 12 10 8 points on the class scoreboard  fifth place loses one point  and each place below loses one more  recommended participant events pay 50 30 15 10  fifth place loses two points  each place below loses two more  the relay pays three times those values  the winning team of a team competition takes 500 points  after combined class scores are reviewed  100 class points are deducted from the first  second  and third year batches of the two classes on the losing team  chabashira adds that points move class by class  not just by team  grade ranking is separate  50 class points to each grade s first place class  no change for second  50 deducted for third  100 for fourth  first place in an individual competition chooses 5000 private points or three written test points  second chooses 3000 or two  third chooses 1000 or one   test points accepted this way cannot be given to another student  the lowest scorer in an individual competition loses 1000 private points  or one written test point if they have fewer than 1000  overall mvp  100 000 private points  each grade s top three scorers  10 000 private points apiece  the ten lowest scoring students in each year lose ten points on their next written exam   for first years the penalty is a written exam deduction  a substitute for a recommended participant event costs 100 000 private points per competition","h":"<article class=\"card\" id=\"sc-private-points-y1v5-p17-1\"><h3><span class=\"ttl\"><a href=\"../../../school/system/private-points.html#sc-private-points-y1v5-p17-1\">Ch.2: the sports festival’s point economy<\/a><\/span><span class=\"meta\">Y1V5 · p.17–23<\/span><span class=\"by\">notes on <a href=\"../../../school/system/private-points.html\">Private Points<\/a><\/span><\/h3><p class=\"setup\">Chabashira’s handout prices the school sports festival in private points, test points and class points at once.<\/p><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Rule<\/span> Individual competition placement pays 15/12/10/8 points on the class scoreboard; fifth place loses one point, and each place below loses one more.<span class=\"pg\">p.17<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Recommended-participant events pay 50/30/15/10; fifth place loses two points, each place below loses two more; the relay pays three times those values; the winning team of a team competition takes 500 points.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> After combined class scores are reviewed, 100 class points are deducted from the first-, second- and third-year batches of the two classes on the losing team; Chabashira adds that points move class-by-class, not just by team.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Grade ranking is separate: 50 class points to each grade’s first-place class, no change for second, 50 deducted for third, 100 for fourth.<span class=\"pg\">p.18<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> First place in an individual competition chooses 5000 private points or three written-test points; second chooses 3000 or two; third chooses 1000 or one — test points accepted this way cannot be given to another student.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> The lowest scorer in an individual competition loses 1000 private points, or one written-test point if they have fewer than 1000.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> Overall MVP: 100,000 private points; each grade’s top three scorers: 10,000 private points apiece.<span class=\"pg\">p.19<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> The ten lowest-scoring students in each year lose ten points on their next written exam — for first-years the penalty is a written-exam deduction.<span class=\"pg\">p.20<\/span><\/li><li><span class=\"mlabel\">Rule<\/span> A substitute for a recommended-participant event costs 100,000 private points per competition.<span class=\"pg\">p.23<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-yamauchi-haruki-y1v5-p23-1","v":"y1v5","y":1,"o":6,"k":"","w":"ike-kanji sudou-ken yamauchi-haruki","q":"yamauchi haruki ch 2  2 1  the huddle gathers with sudou and ike around horikita the moment free homeroom starts  the pair voice the demand for a personal shot at points  only ike s lines are tagged by the translation  sudou s recommended events claim brushes them off  he and ike appear frustrated but say nothing  the  we want a chance  speeches sit untagged between horikita and sudou   the translation does not say whether ike or yamauchi speaks them","h":"<article class=\"card\" id=\"sc-yamauchi-haruki-y1v5-p23-1\"><h3><span class=\"ttl\"><a href=\"../../../people/yamauchi-haruki.html#sc-yamauchi-haruki-y1v5-p23-1\">Ch.2 §2.1: the huddle<\/a><\/span><span class=\"meta\">Y1V5 · p.23–25<\/span><span class=\"by\">notes on <a href=\"../../../people/yamauchi-haruki.html\">Yamauchi Haruki<\/a><\/span><\/h3><p class=\"setup\">Gathers with Sudou and Ike around Horikita the moment free homeroom starts.<\/p><p class=\"with\">with <a href=\"../../../people/ike-kanji.html\">Ike Kanji<\/a> · <a href=\"../../../people/sudou-ken.html\">Sudō Ken<\/a><\/p><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ike Kanji<\/b> The pair voice the demand for a personal shot at points; only Ike’s lines are tagged by the translation.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sudō Ken<\/b> Sudou’s recommended-events claim brushes them off; he and Ike appear frustrated but say nothing.<span class=\"pg\">p.24<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> The “we want a chance” speeches sit untagged between Horikita and Sudou — the translation does not say whether Ike or Yamauchi speaks them.<span class=\"pg\">p.24<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-sports-festival-y1v5-p26-1","v":"y1v5","y":1,"o":6,"k":"","w":"fujimaki katsuragi-kouhei ryuuen-kakeru ichinose-honami","q":"sports festival ch 2  2 2  the assembly gymnasium 1  four hundred strong  fujimaki briefs the red team  first year class a assembles under katsuragi  class c walks out  sakayanagi is introduced  and the class a class d pact is struck  only the final event   the 1200 metre relay   brings all classes from all grade levels together  every other event is divided by grade level  third year class a takes red team command in place of the student council president  class a and class d agree to keep out of each other s way  no shared competition details  only a meeting to come for the group events  ryuuen refuses class b s cooperation talk and walks class c out   the white team s first year halves open the festival estranged  ichinose confronts the walkout to his face and gets gratitude for the trouble saved","h":"<article class=\"card\" id=\"sc-sports-festival-y1v5-p26-1\"><h3><span class=\"ttl\"><a href=\"../../../school/exam/sports-festival.html#sc-sports-festival-y1v5-p26-1\">Ch.2 §2.2: the assembly<\/a><\/span><span class=\"meta\">Y1V5 · p.26–34<\/span><span class=\"by\">notes on <a href=\"../../../school/exam/sports-festival.html\">Sports Festival<\/a><\/span><\/h3><p class=\"setup\">Gymnasium 1, four hundred strong: Fujimaki briefs the Red Team, first-year Class A assembles under Katsuragi, Class C walks out, Sakayanagi is introduced, and the Class A–Class D pact is struck.<\/p><p class=\"with\">with <a href=\"../../../people/index.html#fujimaki\">Fujimaki<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Rule<\/span> Only the final event — the 1200-metre relay — brings all classes from all grade levels together; every other event is divided by grade level.<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Fujimaki<\/b> Third-year Class A takes Red Team command in place of the student council president.<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Class A and Class D agree to keep out of each other’s way: no shared competition details, only a meeting to come for the group events.<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Ryuuen refuses Class B’s cooperation talk and walks Class C out — the White Team’s first-year halves open the festival estranged.<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Ichinose confronts the walkout to his face and gets gratitude for the trouble saved.<span class=\"pg\">p.27<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-sports-festival-y1v5-p16-1\">← Before: Ch.2 §2.1: the rules briefing<\/button><\/div><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v5-p26-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-manabu katsuragi-kouhei sakayanagi-arisu ichinose-honami ryuuen-kakeru ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 2  2 2  the red team assembly over four hundred people gather in gymnasium 1  fujimaki takes red team command  first year class a assembles under katsuragi  ryuuen walks class c out  sakayanagi arisu is introduced  and ayanokoji and horikita argue strategy in the corner  notes that the student council president does not take red team command and wonders when he will make a move  takes the class a class d pact at face value   no shared competition details  only a promise not to get in each other s way  reads the gym s layout  a clear line between katsuragi s followers and nearly all the students sitting with sakayanagi  reconsiders which faction is superior  cites her as the kind who might put feelings aside for victory if ryuuen and class b reconcile  warns horikita that ryuuen likely already has one or more tactics in mind for the festival   the school has never once called the festival a  special exam   i think the sports festival is supposed to do the same with our physical abilities   you re looking for loopholes   you re not thinking big enough    his read on horikita s tunnel vision   we need to make sure that we re prepared  that s all there is to it   there s a good chance that he has a plan in place   we have to think like that to rise to class a s level  has studied ryuuen s strategies and thought processes ever since the fight that nearly got sudou expelled","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v5-p26-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v5-p26-1\">Ch.2 §2.2: the Red Team assembly<\/a><\/span><span class=\"meta\">Y1V5 · p.26–34<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">Over four hundred people gather in Gymnasium 1: Fujimaki takes Red Team command, first-year Class A assembles under Katsuragi, Ryuuen walks Class C out, Sakayanagi Arisu is introduced, and Ayanokōji and Horikita argue strategy in the corner.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “The school has never once called the festival a ‘special exam.’”<span class=\"pg\">p.32<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “I think the sports festival is supposed to do the same with our physical abilities.”<span class=\"pg\">p.32<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “You’re looking for loopholes.”<span class=\"pg\">p.33<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Notes that the student council president does not take Red Team command and wonders when he will make a move.<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Takes the Class A–Class D pact at face value — no shared competition details, only a promise not to get in each other’s way.<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Reads the gym’s layout: a clear line between Katsuragi’s followers and nearly all the students sitting with Sakayanagi; reconsiders which faction is superior.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Cites her as the kind who might put feelings aside for victory if Ryuuen and Class B reconcile.<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Warns Horikita that Ryuuen likely already has one or more tactics in mind for the festival.<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You’re not thinking big enough,” — his read on Horikita’s tunnel vision.<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We need to make sure that we’re prepared. That’s all there is to it,”<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “There’s a good chance that he has a plan in place.”<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “We have to think like that to rise to Class A’s level,”<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Has studied Ryuuen’s strategies and thought processes ever since the fight that nearly got Sudou expelled.<span class=\"pg\">p.34<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p16-1\">← Before: Ch.2 §2.1: the rules and the huddle<\/button><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p35-1\">→ After: Ch.2 §2.3: the gate<\/button><\/div><\/article>"},{"i":"sc-fujimaki-y1v5-p26-1","v":"y1v5","y":1,"o":6,"k":"action spoken","w":"horikita-manabu fujimaki","q":"fujimaki ch 2  2 2  red team command steps forward in the crowded gymnasium 1 among instructors and students and takes command of the red team for the sports festival   i m fujimaki  from the third year class a  announced as the student who will assume command of red team   the student council president does not take it   however  each and every one of them is a crucial battle in which you stake your survival at this school    his warning that future exams wear games  clothes   the only competition which all classes from all grade levels will participate in together is the final event the 1200 meter relay race  releases the first years to gather and discuss strategies by grade level  starting immediately  takes the command the student council president declined  ayanokoji notes the absence and wonders when he will move  no first name is printed anywhere in the chapter","h":"<article class=\"card\" id=\"sc-fujimaki-y1v5-p26-1\"><h3><span class=\"ttl\">Ch.2 §2.2: Red Team command<\/span><span class=\"meta\">Y1V5 · p.26–27<\/span><span class=\"by\">notes on <a href=\"../../../people/index.html#fujimaki\">Fujimaki<\/a><\/span><\/h3><p class=\"setup\">Steps forward in the crowded Gymnasium 1 among instructors and students and takes command of the Red Team for the sports festival.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Fujimaki<\/b> “I’m Fujimaki, from the third-year Class A.”<span class=\"pg\">p.26<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Fujimaki<\/b> “However, each and every one of them is a crucial battle in which you stake your survival at this school,” — his warning that future exams wear games’ clothes.<span class=\"pg\">p.26<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Fujimaki<\/b> “The only competition which all classes from all grade levels will participate in together is the final event—the 1200-meter relay race.”<span class=\"pg\">p.26<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Post<\/span> Announced as the student who will assume command of Red Team — the student council president does not take it.<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Releases the first-years to gather and discuss strategies by grade level, starting immediately.<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Takes the command the student council president declined; Ayanokōji notes the absence and wonders when he will move.<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> No first name is printed anywhere in the chapter.<span class=\"pg\">p.26<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-hirata-yousuke-y1v5-p26-1","v":"y1v5","y":1,"o":6,"k":"action spoken","w":"katsuragi-kouhei sakayanagi-arisu hirata-yousuke","q":"hirata yosuke ch 2  2 2  the assembly meets katsuragi at the red team assembly and becomes class d s negotiating face   i look forward to working with you  accepts the keep out of each other s way pact   no shared competition details   and thanks him with  i m counting on you   it s pretty hard to trust other people in this school  katsuragi kun   so  you won t share any details about the competitions you re participating in  reassures her when she apologizes for being consistently absent   you have nothing to apologize for  looks to the rest of the class for the pact s final decision  no one objects","h":"<article class=\"card\" id=\"sc-hirata-yousuke-y1v5-p26-1\"><h3><span class=\"ttl\"><a href=\"../../../people/hirata-yousuke.html#sc-hirata-yousuke-y1v5-p26-1\">Ch.2 §2.2: the assembly<\/a><\/span><span class=\"meta\">Y1V5 · p.26–34<\/span><span class=\"by\">notes on <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/span><\/h3><p class=\"setup\">Meets Katsuragi at the Red Team assembly and becomes Class D’s negotiating face.<\/p><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “I look forward to working with you,”<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “It’s pretty hard to trust other people in this school, Katsuragi-kun.”<span class=\"pg\">p.31<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Hirata Yōsuke<\/b> “So, you won’t share any details about the competitions you’re participating in?”<span class=\"pg\">p.31<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Accepts the keep-out-of-each-other’s-way pact — no shared competition details — and thanks him with “I’m counting on you.”<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Reassures her when she apologizes for being consistently absent.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “You have nothing to apologize for.”<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">What happens<\/span> Looks to the rest of the class for the pact’s final decision; no one objects.<span class=\"pg\">p.31<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-hirata-yousuke-y1v5-p16-1\">← Before: Ch.2 §2.1: the briefing<\/button><\/div><\/article>"},{"i":"sc-horikita-manabu-y1v5-p26-1","v":"y1v5","y":1,"o":6,"k":"","w":"horikita-suzune fujimaki horikita-manabu","q":"horikita manabu ch 2  passing mention named as the third year class a student and student council president suzune is scanning for  he does not take red team command  she has never sought him out first   he always initiates contact   and cannot find him in the four hundred strong crowd  fujimaki s command of the red team makes ayanokoji wonder when the president will make a move","h":"<article class=\"card\" id=\"sc-horikita-manabu-y1v5-p26-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-manabu.html#sc-horikita-manabu-y1v5-p26-1\">Ch.2: passing mention<\/a><\/span><span class=\"meta\">Y1V5 · p.26<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a><\/span><\/h3><p class=\"setup\">Named as the third-year Class A student and student council president Suzune is scanning for; he does not take Red Team command.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a> · <a href=\"../../../people/index.html#fujimaki\">Fujimaki<\/a><\/p><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Suzune<\/b> She has never sought him out first — he always initiates contact — and cannot find him in the four-hundred-strong crowd.<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Fujimaki<\/b> Fujimaki’s command of the Red Team makes Ayanokōji wonder when the president will make a move.<span class=\"pg\">p.26<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-horikita-suzune-y1v5-p26-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"horikita-manabu katsuragi-kouhei ayanokouji-kiyotaka ryuuen-kakeru ichinose-honami horikita-suzune","q":"horikita suzune ch 2  2 2  the assembly and the coin in gymnasium 1 she scans restlessly for her brother  he never takes red team command  and fujimaki does instead  has never gone to meet him first   he always initiates contact   and cannot spot him in the crowd of four hundred  gets his warning about ryuuen and answers with a pointed question about personal experience  he leaves it at  i ve warned you  pulls him into the strategy question   what factor besides athleticism decides the festival   and gets  mere luck  for her trouble   i m not talking about random chance  though    wants a definite method  not luck  carries shame over her island mistakes  the narration reads her as even more obsessed with victory   different  i think it s the same kind of special exam    against ayanokoji s distinction   i definitely want class d to win    retort when he says she wants loopholes  not preparation   so  you re saying that we need to fight clean and fight hard to win   wait  are you saying that classes b and c are working together behind the scenes   but if that s true  it s crazy    can t believe ryuuen could have a plan already   fine  do enlighten me    swallows the rudeness and asks to be set straight  defends her b and c reading against his push  she thinks a behind the scenes deal is unlikely  suggests ichinose might set aside her feelings and cooperate with ryuuen for victory   ayanokoji calls the view too small","h":"<article class=\"card\" id=\"sc-horikita-suzune-y1v5-p26-1\"><h3><span class=\"ttl\"><a href=\"../../../people/horikita-suzune.html#sc-horikita-suzune-y1v5-p26-1\">Ch.2 §2.2: the assembly and the coin<\/a><\/span><span class=\"meta\">Y1V5 · p.26–34<\/span><span class=\"by\">notes on <a href=\"../../../people/horikita-suzune.html\">Horikita Suzune<\/a><\/span><\/h3><p class=\"setup\">In Gymnasium 1 she scans restlessly for her brother; he never takes Red Team command, and Fujimaki does instead.<\/p><p class=\"with\">with <a href=\"../../../people/horikita-manabu.html\">Horikita Manabu<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “I’m not talking about random chance, though,” — wants a definite method, not luck.<span class=\"pg\">p.32<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “Different? I think it’s the same kind of special exam.” — against Ayanokōji’s distinction.<span class=\"pg\">p.32<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Horikita Suzune<\/b> “I definitely want Class D to win,” — retort when he says she wants loopholes, not preparation.<span class=\"pg\">p.33<\/span><\/li><\/ul><details class=\"more\"><summary>10 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Horikita Manabu<\/b> Has never gone to meet him first — he always initiates contact — and cannot spot him in the crowd of four hundred.<span class=\"pg\">p.26<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Gets his warning about Ryuuen and answers with a pointed question about personal experience; he leaves it at “I’ve warned you.”<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Pulls him into the strategy question — what factor besides athleticism decides the festival — and gets “Mere luck?” for her trouble.<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Carries shame over her island mistakes; the narration reads her as even more obsessed with victory.<span class=\"pg\">p.32<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “So, you’re saying that we need to fight clean and fight hard to win?”<span class=\"pg\">p.33<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Wait. Are you saying that Classes B and C are working together behind the scenes?”<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “But if that’s true, it’s crazy.” — can’t believe Ryuuen could have a plan already.<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Fine, do enlighten me.” — swallows the rudeness and asks to be set straight.<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Defends her B-and-C reading against his push; she thinks a behind-the-scenes deal is unlikely.<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Suggests Ichinose might set aside her feelings and cooperate with Ryuuen for victory — Ayanokōji calls the view too small.<span class=\"pg\">p.34<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-horikita-suzune-y1v5-p16-1\">← Before: Ch.2 §2.1: the briefing and the huddle<\/button><\/div><\/article>"},{"i":"sc-katsuragi-kouhei-y1v5-p26-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"hirata-yousuke ryuuen-kakeru sakayanagi-arisu totsuka-yahiko katsuragi-kouhei","q":"katsuragi kohei ch 2  2 2  the class a face assembles the first year class a students in droves after fujimaki s speech and becomes the class s negotiating face at the red team meeting   i hope we can join forces without any problems  strikes the keep out of each other s way pact with hirata   no shared competition details  only a meeting to come for the group events   i was thinking that it d be best if we just keep out of each other s way   letting that information slip might lead to unnecessary conflict down the road   i ll consult with everyone else  warns horikita off him  he ll laugh while he attacks in the same instant   and leaves his own experience unspoken   don t underestimate ryuuen   i ve warned you  introduces sakayanagi by name and asks for sensitivity  watches her quietly while nearly all the class sits with her faction   that s sakayanagi arisu  yahiko is named among the few boys and girls sitting on his side of the line  the narration reads his faction as possibly no longer superior   sakayanagi may be demonstrating her power deliberately","h":"<article class=\"card\" id=\"sc-katsuragi-kouhei-y1v5-p26-1\"><h3><span class=\"ttl\"><a href=\"../../../people/katsuragi-kouhei.html#sc-katsuragi-kouhei-y1v5-p26-1\">Ch.2 §2.2: the Class A face<\/a><\/span><span class=\"meta\">Y1V5 · p.26–31<\/span><span class=\"by\">notes on <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/span><\/h3><p class=\"setup\">Assembles the first-year Class A students in droves after Fujimaki’s speech and becomes the class’s negotiating face at the Red Team meeting.<\/p><p class=\"with\">with <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a> · <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a> · <a href=\"../../../people/totsuka-yahiko.html\">Totsuka Yahiko<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> “I hope we can join forces without any problems,”<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> “I was thinking that it’d be best if we just keep out of each other’s way.”<span class=\"pg\">p.31<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Katsuragi Kōhei<\/b> “Letting that information slip might lead to unnecessary conflict down the road.”<span class=\"pg\">p.31<\/span><\/li><\/ul><details class=\"more\"><summary>9 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Strikes the keep-out-of-each-other’s-way pact with Hirata — no shared competition details, only a meeting to come for the group events.<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ll consult with everyone else.”<span class=\"pg\">p.31<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Warns Horikita off him: he’ll laugh while he attacks in the same instant — and leaves his own experience unspoken.<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “Don’t underestimate Ryuuen.”<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “I’ve warned you.”<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> Introduces Sakayanagi by name and asks for sensitivity; watches her quietly while nearly all the class sits with her faction.<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Spoken<\/span> “That’s Sakayanagi Arisu.”<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Totsuka Yahiko<\/b> Yahiko is named among the few boys and girls sitting on his side of the line.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Position<\/span> The narration reads his faction as possibly no longer superior — Sakayanagi may be demonstrating her power deliberately.<span class=\"pg\">p.30<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ichinose-honami-y1v5-p27-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"ryuuen-kakeru ayanokouji-kiyotaka ichinose-honami","q":"ichinose honami ch 2  2 2  confronting the walkout interrupts katsuragi s briefing as almost her entire class s counterpart walks out   she questions ryuuen to his face   so  you don t intend to hold a discussion   i see  so  you re just saving us the hassle  then   you really think you can win without cooperating  gets gratitude for the trouble saved and his sneer as an answer  class c leaves anyway  ayanokoji later names her as the kind who might set feelings aside and cooperate with ryuuen for victory","h":"<article class=\"card\" id=\"sc-ichinose-honami-y1v5-p27-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ichinose-honami.html#sc-ichinose-honami-y1v5-p27-1\">Ch.2 §2.2: confronting the walkout<\/a><\/span><span class=\"meta\">Y1V5 · p.27<\/span><span class=\"by\">notes on <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a><\/span><\/h3><p class=\"setup\">Interrupts Katsuragi’s briefing as almost her entire class’s counterpart walks out — she questions Ryuuen to his face.<\/p><p class=\"with\">with <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “So, you don’t intend to hold a discussion?”<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “I see. So, you’re just saving us the hassle, then,”<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ichinose Honami<\/b> “You really think you can win without cooperating?”<span class=\"pg\">p.27<\/span><\/li><\/ul><details class=\"more\"><summary>2 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ryūen Kakeru<\/b> Gets gratitude for the trouble saved and his sneer as an answer; Class C leaves anyway.<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Ayanokōji later names her as the kind who might set feelings aside and cooperate with Ryuuen for victory.<span class=\"pg\">p.33<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ryuuen-kakeru-y1v5-p27-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"ichinose-honami manabe-shiho katsuragi-kouhei ayanokouji-kiyotaka ryuuen-kakeru","q":"ryuen kakeru ch 2  2 2  the walkout when ichinose asks why class c won t discuss strategy  he turns with his hands in his pockets and leads the whole class out of the gym   it s a waste of time   you should be grateful   hmm  i wonder    to ichinose s challenge on winning without cooperating  refuses her cooperation talk to her face  the exit confirms class c s dictatorship  manabe follows him out after the glance back at karuizawa  katsuragi s warning to horikita is keyed to him  he ll laugh while he attacks in the same instant  ayanokoji s read  always looking to win  possibly already holding one or more festival tactics behind the b and c refusal  the walkout confirms his hold on class c inside the volume s first pages","h":"<article class=\"card\" id=\"sc-ryuuen-kakeru-y1v5-p27-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ryuuen-kakeru.html#sc-ryuuen-kakeru-y1v5-p27-1\">Ch.2 §2.2: the walkout<\/a><\/span><span class=\"meta\">Y1V5 · p.27–28<\/span><span class=\"by\">notes on <a href=\"../../../people/ryuuen-kakeru.html\">Ryūen Kakeru<\/a><\/span><\/h3><p class=\"setup\">When Ichinose asks why Class C won’t discuss strategy, he turns with his hands in his pockets and leads the whole class out of the gym.<\/p><p class=\"with\">with <a href=\"../../../people/ichinose-honami.html\">Ichinose Honami<\/a> · <a href=\"../../../people/manabe-shiho.html\">Manabe Shiho<\/a> · <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “It’s a waste of time,”<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “You should be grateful.”<span class=\"pg\">p.27<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ryūen Kakeru<\/b> “Hmm, I wonder.” — to Ichinose’s challenge on winning without cooperating.<span class=\"pg\">p.27<\/span><\/li><\/ul><details class=\"more\"><summary>5 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ichinose Honami<\/b> Refuses her cooperation talk to her face; the exit confirms Class C’s dictatorship.<span class=\"pg\">p.27<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Manabe Shiho<\/b> Manabe follows him out after the glance-back at Karuizawa.<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> Katsuragi’s warning to Horikita is keyed to him: he’ll laugh while he attacks in the same instant.<span class=\"pg\">p.28<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Ayanokōji’s read: always looking to win, possibly already holding one or more festival tactics behind the B-and-C refusal.<span class=\"pg\">p.34<\/span><\/li><li><span class=\"mlabel\">Position<\/span> The walkout confirms his hold on Class C inside the volume’s first pages.<span class=\"pg\">p.27<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-karuizawa-kei-y1v5-p28-1","v":"y1v5","y":1,"o":6,"k":"","w":"manabe-shiho karuizawa-kei","q":"karuizawa kei ch 2  2 2  the class c exit as class c files out of the gym  her expression sours for an instant at manabe s glance  manabe looks back at her from ryuuen s wake   the cruise ship scrap and bullying history   then averts her eyes and follows the class out","h":"<article class=\"card\" id=\"sc-karuizawa-kei-y1v5-p28-1\"><h3><span class=\"ttl\"><a href=\"../../../people/karuizawa-kei.html#sc-karuizawa-kei-y1v5-p28-1\">Ch.2 §2.2: the Class C exit<\/a><\/span><span class=\"meta\">Y1V5 · p.28<\/span><span class=\"by\">notes on <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/span><\/h3><p class=\"setup\">As Class C files out of the gym, her expression sours for an instant at Manabe’s glance.<\/p><p class=\"with\">with <a href=\"../../../people/manabe-shiho.html\">Manabe Shiho<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Manabe Shiho<\/b> Manabe looks back at her from Ryuuen’s wake — the cruise-ship scrap and bullying history — then averts her eyes and follows the class out.<span class=\"pg\">p.28<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-karuizawa-kei-y1v5-p13-1\">← Before: Ch.2: the zodiac debrief at Pallet<\/button><\/div><\/article>"},{"i":"sc-manabe-shiho-y1v5-p28-1","v":"y1v5","y":1,"o":6,"k":"","w":"karuizawa-kei manabe-shiho","q":"manabe shiho ch 2  passing mention as class c leaves the gym  manabe looks back at karuizawa for a moment  averts her eyes  and follows ryuuen out  the glance reopens the cruise ship scrap where karuizawa s bullying history surfaced","h":"<article class=\"card\" id=\"sc-manabe-shiho-y1v5-p28-1\"><h3><span class=\"ttl\"><a href=\"../../../people/manabe-shiho.html#sc-manabe-shiho-y1v5-p28-1\">Ch.2: passing mention<\/a><\/span><span class=\"meta\">Y1V5 · p.28<\/span><span class=\"by\">notes on <a href=\"../../../people/manabe-shiho.html\">Manabe Shiho<\/a><\/span><\/h3><p class=\"setup\">As Class C leaves the gym, Manabe looks back at Karuizawa for a moment, averts her eyes, and follows Ryuuen out.<\/p><p class=\"with\">with <a href=\"../../../people/karuizawa-kei.html\">Karuizawa Kei<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Karuizawa Kei<\/b> The glance reopens the cruise-ship scrap where Karuizawa’s bullying history surfaced.<span class=\"pg\">p.28<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-sakayanagi-arisu-y1v5-p28-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"katsuragi-kouhei hirata-yousuke sakayanagi-arisu","q":"sakayanagi arisu ch 2  2 2  the introduction first full appearance  the petite girl alone with a thin cane  introduced by katsuragi as disabled   class a s other rumored leader   unfortunately  i won t be very useful in this competition   your kindness overwhelms me    to the class d boys who rush to reassure her  the class s line is clear between his followers and hers  nearly all the students sit with her   perhaps a deliberate demonstration  hirata reassures her when she apologizes for being consistently absent  short silver hair  pale skin  a dreamlike quality that makes people instinctively want to protect her   and a strength of will behind the weakness  did not participate in the island or cruise ship tests  whether a penalty was incurred is left open by the page","h":"<article class=\"card\" id=\"sc-sakayanagi-arisu-y1v5-p28-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakayanagi-arisu.html#sc-sakayanagi-arisu-y1v5-p28-1\">Ch.2 §2.2: the introduction<\/a><\/span><span class=\"meta\">Y1V5 · p.28–31<\/span><span class=\"by\">notes on <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/span><\/h3><p class=\"setup\">First full appearance: the petite girl alone with a thin cane, introduced by Katsuragi as disabled — Class A’s other rumored leader.<\/p><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a> · <a href=\"../../../people/hirata-yousuke.html\">Hirata Yōsuke<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “Unfortunately, I won’t be very useful in this competition.”<span class=\"pg\">p.30<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Sakayanagi Arisu<\/b> “Your kindness overwhelms me,” — to the Class D boys who rush to reassure her.<span class=\"pg\">p.30<\/span><\/li><\/ul><details class=\"more\"><summary>4 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> The class’s line is clear between his followers and hers; nearly all the students sit with her — perhaps a deliberate demonstration.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Hirata Yōsuke<\/b> Hirata reassures her when she apologizes for being consistently absent.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Feat<\/span> Short silver hair, pale skin, a dreamlike quality that makes people instinctively want to protect her — and a strength of will behind the weakness.<span class=\"pg\">p.30<\/span><\/li><li><span class=\"mlabel\">Position<\/span> Did not participate in the island or cruise ship tests; whether a penalty was incurred is left open by the page.<span class=\"pg\">p.31<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-sakura-airi-y1v5-p30-1","v":"y1v5","y":1,"o":6,"k":"","w":"sakayanagi-arisu sakura-airi","q":"sakura airi ch 2  passing mention named in the narration comparing sakayanagi s looks to kushida and her  one of the two girls sakayanagi is measured against when class d s boys size her up","h":"<article class=\"card\" id=\"sc-sakura-airi-y1v5-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/sakura-airi.html#sc-sakura-airi-y1v5-p30-1\">Ch.2: passing mention<\/a><\/span><span class=\"meta\">Y1V5 · p.30<\/span><span class=\"by\">notes on <a href=\"../../../people/sakura-airi.html\">Sakura Airi<\/a><\/span><\/h3><p class=\"setup\">Named in the narration comparing Sakayanagi’s looks to Kushida and her.<\/p><p class=\"with\">with <a href=\"../../../people/sakayanagi-arisu.html\">Sakayanagi Arisu<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Sakayanagi Arisu<\/b> One of the two girls Sakayanagi is measured against when Class D’s boys size her up.<span class=\"pg\">p.30<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-totsuka-yahiko-y1v5-p30-1","v":"y1v5","y":1,"o":6,"k":"","w":"katsuragi-kouhei totsuka-yahiko","q":"totsuka yahiko ch 2  passing mention named among the boys sitting with katsuragi s faction in the class a split  one of the few class a students counted on katsuragi s side of the line","h":"<article class=\"card\" id=\"sc-totsuka-yahiko-y1v5-p30-1\"><h3><span class=\"ttl\"><a href=\"../../../people/totsuka-yahiko.html#sc-totsuka-yahiko-y1v5-p30-1\">Ch.2: passing mention<\/a><\/span><span class=\"meta\">Y1V5 · p.30<\/span><span class=\"by\">notes on <a href=\"../../../people/totsuka-yahiko.html\">Totsuka Yahiko<\/a><\/span><\/h3><p class=\"setup\">Named among the boys sitting with Katsuragi’s faction in the Class A split.<\/p><p class=\"with\">with <a href=\"../../../people/katsuragi-kouhei.html\">Katsuragi Kōhei<\/a><\/p><details class=\"more\"><summary>1 more note<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Katsuragi Kōhei<\/b> One of the few Class A students counted on Katsuragi’s side of the line.<span class=\"pg\">p.30<\/span><\/li><\/ul><\/details><\/article>"},{"i":"sc-ayanokouji-kiyotaka-y1v5-p35-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"chabashira-sae ayanokouji-kiyotaka","q":"ayanokoji kiyotaka ch 2  2 3  the gate after class he stays behind alone with a file on his phone   whatever it showed  he decides no traps are necessary   then runs into chabashira spraying water at the main gate   are you on duty today   don t you think that s an exaggeration   no  nothing like that    to chabashira s guess that he already has an eccentric strategy in place   i m free to decide my own path  she warns that if he shows no results soon she ll stop covering for him  the confrontation was only a matter of time  blank short scan page inside the dialogue  footer and watermark only  p 38 is likewise a blank scan","h":"<article class=\"card\" id=\"sc-ayanokouji-kiyotaka-y1v5-p35-1\"><h3><span class=\"ttl\"><a href=\"../../../people/ayanokouji-kiyotaka.html#sc-ayanokouji-kiyotaka-y1v5-p35-1\">Ch.2 §2.3: the gate<\/a><\/span><span class=\"meta\">Y1V5 · p.35–38<\/span><span class=\"by\">notes on <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/span><\/h3><p class=\"setup\">After class he stays behind alone with a file on his phone — whatever it showed, he decides no traps are necessary — then runs into Chabashira spraying water at the main gate.<\/p><p class=\"with\">with <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Are you on duty today?”<span class=\"pg\">p.35<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “Don’t you think that’s an exaggeration?”<span class=\"pg\">p.37<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Ayanokōji Kiyotaka<\/b> “No, nothing like that,” — to Chabashira’s guess that he already has an eccentric strategy in place.<span class=\"pg\">p.37<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “I’m free to decide my own path.”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Chabashira Sae<\/b> She warns that if he shows no results soon she’ll stop covering for him; the confrontation was only a matter of time.<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Blank/short scan page inside the dialogue (footer and watermark only); p.38 is likewise a blank scan.<span class=\"pg\">p.36<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-ayanokouji-kiyotaka-y1v5-p26-1\">← Before: Ch.2 §2.2: the Red Team assembly<\/button><\/div><\/article>"},{"i":"sc-chabashira-sae-y1v5-p35-1","v":"y1v5","y":1,"o":6,"k":"spoken","w":"ayanokouji-kiyotaka chabashira-sae","q":"chabashira sae ch 2  2 3  the gate spraying water at the main gate after school  she s on duty and clocks that he stayed behind later than usual   you stayed behind longer than usual  ayanokouji   are you prepared for the sports festival   in your case  i would have thought that you d already have some eccentric idea or strategy in place   but if you don t show me some results soon  i ll stop covering for you  their talk stops when their eyes meet   public discussion helps no one  she accepts his right to choose his path but puts a deadline on her cover  blank short scan page sits inside the dialogue  footer and watermark only","h":"<article class=\"card\" id=\"sc-chabashira-sae-y1v5-p35-1\"><h3><span class=\"ttl\"><a href=\"../../../people/chabashira-sae.html#sc-chabashira-sae-y1v5-p35-1\">Ch.2 §2.3: the gate<\/a><\/span><span class=\"meta\">Y1V5 · p.35–37<\/span><span class=\"by\">notes on <a href=\"../../../people/chabashira-sae.html\">Chabashira Sae<\/a><\/span><\/h3><p class=\"setup\">Spraying water at the main gate after school; she’s on duty and clocks that he stayed behind later than usual.<\/p><p class=\"with\">with <a href=\"../../../people/ayanokouji-kiyotaka.html\">Ayanokōji Kiyotaka<\/a><\/p><ul class=\"lines\"><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “You stayed behind longer than usual, Ayanokouji.”<span class=\"pg\">p.35<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “Are you prepared for the sports festival?”<span class=\"pg\">p.37<\/span><\/li><li class=\"q spoken\"><b class=\"sp\">Chabashira Sae<\/b> “In your case, I would have thought that you’d already have some eccentric idea or strategy in place,”<span class=\"pg\">p.37<\/span><\/li><\/ul><details class=\"more\"><summary>3 more notes<\/summary><ul class=\"rows\"><li><span class=\"mlabel\">Spoken<\/span> “But if you don’t show me some results soon, I’ll stop covering for you.”<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Relationship<\/span> <b class=\"sp\">Ayanokōji Kiyotaka<\/b> Their talk stops when their eyes meet — public discussion helps no one; she accepts his right to choose his path but puts a deadline on her cover.<span class=\"pg\">p.37<\/span><\/li><li><span class=\"mlabel\">Caveat<\/span> Blank/short scan page sits inside the dialogue (footer and watermark only).<span class=\"pg\">p.36<\/span><\/li><\/ul><\/details><div class=\"ptrs\"><button type=\"button\" class=\"ptr\" data-go=\"sc-chabashira-sae-y1v5-p16-1\">← Before: Ch.2 §2.1: the sports festival briefing<\/button><\/div><\/article>"}];
